    fn format_constructor_lookup_guard_wrapper_lea(&mut self, r: Resources<'_, Self>, ctor: &mut c::Calls<Self::FormatConstructorCallOwner>, lookup: &mut l::Calls<Self::FormatLookupCallOwner>, guard: &mut Option<g::CallReturned<Self::FormatLookupGuardCallOwner>>, source_tail: Option<&mut Option<g::native_return::TailCallReturned<Self::FormatLookupGuardTailOwner>>>, call: &mut Option<n::CallReturned<Self::FormatLookupGuardWrapperCallOwner>>, tail: &mut Option<n::TailReturned<Self::FormatLookupGuardWrapperTailOwner>>, pc: u32, address: u64, returned: &mut Option<n::LeaReturned>) -> Result<(), Self::Error>;
    fn format_constructor_lookup_guard_wrapper_add(&mut self, r: Resources<'_, Self>, ctor: &mut c::Calls<Self::FormatConstructorCallOwner>, lookup: &mut l::Calls<Self::FormatLookupCallOwner>, guard: &mut Option<g::CallReturned<Self::FormatLookupGuardCallOwner>>, source_tail: Option<&mut Option<g::native_return::TailCallReturned<Self::FormatLookupGuardTailOwner>>>, call: &mut Option<n::CallReturned<Self::FormatLookupGuardWrapperCallOwner>>, tail: &mut Option<n::TailReturned<Self::FormatLookupGuardWrapperTailOwner>>, returned: &mut Option<n::StackAdjustment>) -> Result<(), Self::Error>;
